import datetime
def normalize(ts):
    if isinstance(ts, (int, float)):
        return datetime.datetime.utcfromtimestamp(ts).isoformat() + "Z"
    for fmt in ("%Y-%m-%d", "%d %b %Y", "%Y/%m/%d"):
        try: return datetime.datetime.strptime(ts, fmt).date().isoformat()
        except ValueError: pass
    return "UNPARSEABLE"
for t in [1614816000, "2021-03-04", "04 Mar 2021"]:
    print(repr(t), "->", normalize(t))

