ids = [("doi:10.1/abc", "Deep Search"), ("arxiv:2101.1", "Deep Search"), ("local:992", "Deep Search")]
clusters = {}
for ident, title in ids:
    clusters.setdefault(title.lower(), []).append(ident)
for title, members in clusters.items():
    print(title, "<->", members)

